{"implementation":"def solve(case):
    nodes = case.get("nodes")
    required_symbols = case.get("required_symbols")
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError("Invalid case structure")
    node_by_id = {}
    for node in nodes:
        nid = node.get("id")
        parent = node.get("parent")
        symbol = node.get("symbol")
        depth = node.get("depth")
        removable = node.get("removable")
        if nid is None or parent is None or symbol is None or depth is None or removable is None:
            raise ValueError("Node missing required field")
        if nid in node_by_id:
            raise ValueError("Duplicate node id")
        node_by_id[nid] = node
    roots = [nid for nid, node in node_by_id.items() if node["parent"] is None]
    if len(roots) != 1:
        raise ValueError("Must have exactly one root")
    root_id = roots[0]
    children = {nid: [] for nid in node_by_id}
    for nid, node in node_by_id.items():
        parent = node["parent"]
        if parent is not None:
            if parent not in node_by_id:
                raise ValueError(f"Parent {parent} not found")
            children[parent].append(nid)
    protected = set()
    protected.add(root_id)
    for nid, node in node_by_id.items():
        if node["symbol"] in required_symbols:
            protected.add(nid)
        if not node["removable"]:
            protected.add(nid)
    remaining = set(node_by_id.keys())
    removal_order = []
    sorted_nodes = sorted(node_by_id.values(), key=lambda n: (-n["depth"], n["id"]))
    for node in sorted_nodes:
        nid = node["id"]
        if nid not in remaining:
            continue
        if nid in protected:
            continue
        if any(child in remaining for child in children.get(nid, [])):
            continue
        safe = True
        for req in required_symbols:
            found = False
            for other_id in remaining:
                if other_id == nid:
                    continue
                if node_by_id[other_id]["symbol"] == req:
                    found = True
                    break
            if not found:
                safe = False
                break
        if safe:
            remaining.remove(nid)
            removal_order.append(nid)
    retained_ids = sorted(remaining)
    return {"retained_ids": retained_ids, "removal_order": removal_order}"}
